@Entity(tableName = "users")
data class User(
    @PrimaryKey val id: Long,
    @ColumnInfo(name = "email_address") val email: String,
)

@Dao interface UserDao {
    @Query("SELECT * FROM users WHERE id = :id")
    fun byId(id: Long): User?
}

object Users : Table("users") {
    val id    = integer("id").autoIncrement()
    val email = varchar("email_address", 200)
    override val primaryKey = PrimaryKey(id)
}

// data class stays dumb; the table object is the metadata
fun find(id: Int) = transaction {
    Users.selectAll().where { Users.id eq id }.singleOrNull()
}
